SELECT jsonb_build_object( 'config',(SELECT jsonb_build_object('guildId',guild_id::text,'linkedRoleId', CASE WHEN linked_role_id IS NULL THEN NULL ELSE to_jsonb(linked_role_id::text) END, 'dateCreated',to_char(date_created AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) FROM zc_private.discord_guild_config WHERE guild_id=$1), 'feeds',COALESCE((SELECT jsonb_agg(jsonb_build_object('guildId',guild_id::text, 'kind',kind,'channelId',channel_id::text,'enabled',enabled,'cursorEventId',cursor_event_id::text, 'dateCreated',to_char(date_created AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ORDER BY kind) FROM zc_private.discord_guild_feed WHERE guild_id=$1),'[]'::jsonb), 'digest',(SELECT jsonb_build_object('guildId',guild_id::text,'channelId',channel_id::text, 'dailyEnabled',daily_enabled,'weeklyEnabled',weekly_enabled,'deliveryHour',delivery_hour, 'weeklyDay',weekly_day,'nextDeliveryAt',CASE WHEN next_delivery_at IS NULL THEN NULL ELSE to_jsonb(to_char(next_delivery_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) END, 'leaseUntil',CASE WHEN lease_until IS NULL THEN NULL ELSE to_jsonb(to_char(lease_until AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) END,'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) FROM zc_private.discord_digest WHERE guild_id=$1), 'tournamentMessages',COALESCE((SELECT jsonb_agg(jsonb_build_object('guildId',guild_id::text, 'idTournament',id_tournament,'channelId',channel_id::text,'messageId',message_id::text, 'contentHash',content_hash,'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))) FROM zc_private.discord_tournament_message WHERE guild_id=$1),'[]'::jsonb)) AS value
